  time: string;
  occupiedSeats: string[];
}

export interface CustomerDetails {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface NewReservation {
  screeningId: number;
  seats: string[];
  customer: CustomerDetails;
  totalPrice: number;
