import { Routes } from '@angular/router';
import { MovieList } from './movie-list/movie-list';
import { Placeholder } from './placeholder';

export const appRoutes: Routes = [
  { path: '', pathMatch: 'full', component: MovieList },
  { path: 'screenings/:id/seats', component: Placeholder },
  { path: 'screenings/:id/summary', component: Placeholder },
  { path: 'screenings/:id/checkout', component: Placeholder },
  { path: 'confirmation', component: Placeholder },
  { path: '**', redirectTo: '' },
];

import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter, withComponentInputBinding } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(appRoutes, withComponentInputBinding()),
    provideNativeDateAdapter(),
    provideHttpClient(),
  ],
};

import { writeFileSync } from 'node:fs';

const FIXED_NOW = '2026-09-14T10:00:00';

export async function connect() {
  const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
  const page = targets.find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => {
    ws.onopen = res;
    ws.onerror = rej;
  });
  let id = 0;
  const pending = new Map();
  const listeners = [];
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    } else if (msg.method) {
      listeners.forEach((l) => l(msg));
    }
  };
  const send = (method, params = {}) =>
    new Promise((resolve) => {
      const reqId = ++id;
      pending.set(reqId, resolve);
      ws.send(JSON.stringify({ id: reqId, method, params }));
    });

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', {
    width: 1280,
    height: 720,
    deviceScaleFactor: 1,
    mobile: false,
  });
  // Pin the browser clock to a date before the screenings so the day logic has data.
  await send('Page.addScriptToEvaluateOnNewDocument', {
    source: `(() => { const FIXED = new Date('${FIXED_NOW}').getTime(); const Real = Date;
      class FakeDate extends Real { constructor(...a) { if (a.length === 0) super(FIXED); else super(...a); }
        static now() { return FIXED; } }
      window.Date = FakeDate; })();`,
  });

  const evaluate = async (expression) => {
    const res = await send('Runtime.evaluate', {
      expression,
      awaitPromise: true,
      returnByValue: true,
    });
    if (res.result.exceptionDetails) {
      throw new Error(JSON.stringify(res.result.exceptionDetails).slice(0, 500));
    }
    return res.result.result.value;
  };

  const navigate = async (url) => {
    await send('Page.navigate', { url });
    await waitFor(`document.readyState === 'complete'`);
    await sleep(600);
  };

  const waitFor = async (expression, timeout = 8000) => {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        if (await evaluate(`Boolean(${expression})`)) return true;
      } catch {}
      await sleep(100);
    }
    throw new Error(`timed out waiting for: ${expression}`);
  };

  const screenshot = async (path) => {
    const res = await send('Page.captureScreenshot', { format: 'png' });
    writeFileSync(path, Buffer.from(res.result.data, 'base64'));
  };

  const close = () => ws.close();
  return { send, evaluate, navigate, waitFor, screenshot, close, listeners };
}

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export function check(label, condition, detail = '') {
  const status = condition ? 'PASS' : 'FAIL';
  console.log(`${status} ${label}${detail ? ` — ${detail}` : ''}`);
  return condition;
}

import { connect, check, sleep } from './cdp.mjs';

const BASE = 'http://localhost:4200';
const results = [];
const expectWeekday = (iso) => ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][new Date(iso + 'T12:00:00').getDay()];

const c = await connect();
const q = (sel) => `document.querySelectorAll(${JSON.stringify(sel)}).length`;

// 1. Default: today is 2026-09-14 (pinned clock); no screenings that day.
await c.navigate(`${BASE}/`);
await c.waitFor(`document.querySelector('[data-testid=movies-empty]')`);
results.push(check('AC-54 empty day shows message', (await c.evaluate(`document.querySelector('[data-testid=movies-empty]').textContent.trim()`)) === 'No screenings on this day'));
results.push(check('AC-54 no cards on empty day', (await c.evaluate(q('[data-testid=movie-card]'))) === 0));
const dayInfo = await c.evaluate(`[...document.querySelectorAll('[data-testid=day-button]')].map(b => ({label: b.textContent.trim(), date: b.dataset.date, sel: b.dataset.selected}))`);
const expectedLabels = ['Today', 1, 2, 3, 4].map((o, i) => (i === 0 ? 'Today' : expectWeekday(addIso('2026-09-14', i))));
results.push(check('AC-52 five day buttons with weekday names', JSON.stringify(dayInfo.map((d) => d.label)) === JSON.stringify(expectedLabels), JSON.stringify(dayInfo.map((d) => d.label))));
results.push(check('AC-52 Today selected by default', dayInfo[0].sel === 'true' && dayInfo.slice(1).every((d) => d.sel === 'false')));
results.push(check('AC-52 datepicker present', (await c.evaluate(q('[data-testid=date-picker]'))) === 1));
results.push(check('AC-52 day-picker contains buttons + datepicker', (await c.evaluate(`document.querySelector('[data-testid=day-picker] [data-testid=date-picker]') !== null`))));

// 2. Choose 2026-09-15 via a day button, URL updates, cards match fixture data.
await c.evaluate(`document.querySelector('[data-date="2026-09-15"]').click()`);
await c.waitFor(`location.search === '?date=2026-09-15' && document.querySelector('[data-testid=movie-card]')`);
const cards = await c.evaluate(`[...document.querySelectorAll('[data-testid=movie-card]')].map(card => ({
  id: card.dataset.movieId,
  title: card.querySelector('[data-testid=movie-title]').textContent.trim(),
  genre: card.querySelector('[data-testid=movie-genre]').textContent.trim(),
  runtime: card.querySelector('[data-testid=movie-runtime]').textContent.trim(),
  format: card.querySelector('[data-testid=movie-format]').textContent.trim(),
  buttons: [...card.querySelectorAll('[data-testid=screening-button]')].map(b => b.textContent.trim() + '#' + b.dataset.screeningId),
}))`);
console.log(JSON.stringify(cards, null, 1));
results.push(check('AC-53 five movies have screenings on 2026-09-15', cards.length === 5, `got ${cards.length}`));
results.push(check('AC-02 first card data', cards[0].title === 'The Silent Harbor' && cards[0].genre === 'Drama' && cards[0].runtime === '128 min' && cards[0].format === 'PL subtitles'));
results.push(check('AC-03 screenings ordered by time', JSON.stringify(cards[0].buttons) === JSON.stringify(['16:00#1', '19:30#2']), cards[0].buttons.join(',')));
results.push(check('AC-03 Sunday Bakers buttons', JSON.stringify(cards[4].buttons) === JSON.stringify(['12:15#17']), cards[4].buttons.join(',')));
results.push(check('AC-02 dubbing format', cards[2].format === 'PL dubbing'));
results.push(check('AC-55 selected button marked', (await c.evaluate(`document.querySelector('[data-date="2026-09-15"]').dataset.selected`)) === 'true'));

// 3. Deep link and invalid/past dates.
await c.navigate(`${BASE}/?date=2026-09-17`);
await c.waitFor(`document.querySelector('[data-testid=movie-card]')`);
results.push(check('AC-55 deep link selects date', (await c.evaluate(`document.querySelector('[data-date="2026-09-17"]').dataset.selected`)) === 'true'));
results.push(check('AC-53 2026-09-17 shows 3 movies', (await c.evaluate(q('[data-testid=movie-card]'))) === 3));
for (const bad of ['?date=2026-02-30', '?date=2026-09-01', '?date=garbage', '']) {
  await c.navigate(`${BASE}/${bad}`);
  await c.waitFor(`document.querySelector('[data-testid=movies-empty], [data-testid=movie-card]')`);
  const sel = await c.evaluate(`document.querySelector('[data-testid=day-button][data-selected=true]')?.dataset.date`);
  results.push(check(`AC-55 "${bad}" selects today`, sel === '2026-09-14', `selected=${sel}`));
}

// 4. Datepicker: a date before today is refused; a future date is chosen.
await c.navigate(`${BASE}/`);
await c.waitFor(`document.querySelector('[data-testid=date-picker]')`);
await setDateInput(c, '9/1/2026');
await sleep(400);
results.push(check('AC-55 past date from datepicker ignored', (await c.evaluate(`location.search`)) === ''));
await setDateInput(c, '9/20/2026');
await c.waitFor(`location.search === '?date=2026-09-20'`).catch(() => {});
results.push(check('datepicker picks future date into URL', (await c.evaluate(`location.search`)) === '?date=2026-09-20', await c.evaluate(`location.search`)));
await c.waitFor(`document.querySelector('[data-testid=movie-card]') || document.querySelector('[data-testid=movies-empty]')`);
results.push(check('datepicker shows date and no day button selected', (await c.evaluate(`document.querySelector('[data-testid=date-picker]').value`)) !== '' && (await c.evaluate(`document.querySelectorAll('[data-testid=day-button][data-selected=true]').length`)) === 0));
await c.screenshot('/tmp/e2e/t01-datepicker.png');

// 5. Screening button navigates to the seat-map route.
await c.navigate(`${BASE}/?date=2026-09-15`);
await c.waitFor(`document.querySelector('[data-testid=screening-button]')`);
await c.evaluate(`document.querySelector('[data-testid=screening-button][data-screening-id="2"]').click()`);
await c.waitFor(`location.pathname === '/screenings/2/seats'`).catch(() => {});
results.push(check('AC-04 screening button navigates', (await c.evaluate(`location.pathname`)) === '/screenings/2/seats'));

// 6. Unknown URL redirects to /.
await c.navigate(`${BASE}/nope/here`);
await c.waitFor(`location.pathname === '/'`).catch(() => {});
results.push(check('unknown URL redirects to /', (await c.evaluate(`location.pathname`)) === '/'));

// 7. Loading and error states, Retry re-issues the request.
await c.send('Fetch.enable', { patterns: [{ urlPattern: '*localhost:3000/movies*' }] });
let failing = true;
c.listeners.push((msg) => {
  if (msg.method === 'Fetch.requestPaused') {
    if (failing) c.send('Fetch.failRequest', { requestId: msg.params.requestId, errorReason: 'Failed' });
    else c.send('Fetch.continueRequest', { requestId: msg.params.requestId });
  }
});
await c.navigate(`${BASE}/?date=2026-09-15`);
await c.waitFor(`document.querySelector('[data-testid=movies-error]')`);
results.push(check('AC-50 error text shown', (await c.evaluate(`document.querySelector('[data-testid=movies-error]').textContent.includes('Failed to load movies')`))));
results.push(check('AC-50 no cards on error', (await c.evaluate(q('[data-testid=movie-card]'))) === 0));
failing = false;
await c.evaluate(`document.querySelector('[data-testid=movies-retry-button]').click()`);
await c.waitFor(`document.querySelector('[data-testid=movie-card]')`);
results.push(check('AC-50 Retry re-issues request and loads', (await c.evaluate(q('[data-testid=movie-card]'))) === 5));
await c.send('Fetch.disable');

// Loading indicator while the movie request is held open.
failing = false;
await c.send('Fetch.enable', { patterns: [{ urlPattern: '*localhost:3000/movies*' }] });
let held = [];
c.listeners.length = 0;
c.listeners.push((msg) => {
  if (msg.method === 'Fetch.requestPaused') held.push(msg.params.requestId);
});
await c.navigate(`${BASE}/?date=2026-09-15`);
await sleep(400);
results.push(check('AC-49 loading indicator while in flight', (await c.evaluate(q('[data-testid=movies-loading]'))) === 1 && (await c.evaluate(q('[data-testid=movie-card]'))) === 0));
for (const id of held) await c.send('Fetch.continueRequest', { requestId: id });
await c.waitFor(`document.querySelector('[data-testid=movie-card]')`);
results.push(check('AC-49 loading indicator gone after load', (await c.evaluate(q('[data-testid=movies-loading]'))) === 0));
await c.send('Fetch.disable');

// Every section 9.1 identifier exists.
const ids = ['day-picker', 'day-button', 'date-picker', 'movie-list', 'movie-card', 'movie-title', 'movie-genre', 'movie-runtime', 'movie-format', 'screening-button'];
await c.navigate(`${BASE}/?date=2026-09-15`);
await c.waitFor(`document.querySelector('[data-testid=screening-button]')`);
const missing = [];
for (const id of ids) if ((await c.evaluate(q(`[data-testid=${id}]`))) === 0) missing.push(id);
results.push(check('AC-51 section 9.1 identifiers present', missing.length === 0, missing.join(',')));

console.log(`\n${results.filter(Boolean).length}/${results.length} checks passed`);
c.close();
process.exit(0);

function addIso(iso, days) {
  const d = new Date(iso + 'T12:00:00');
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}

async function setDateInput(c, text) {
  // Typing into the native-date-adapter input and firing change mirrors a user entry.
  await c.evaluate(`(() => {
    const input = document.querySelector('[data-testid=date-picker]');
    input.focus();
    input.value = ${JSON.stringify(text)};
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    input.blur();
  })()`);
}

