  if (msg.method === 'Fetch.requestPaused') {
    if (failing) c.send('Fetch.failRequest', { requestId: msg.params.requestId, errorReason: 'Failed' });
    else c.send('Fetch.continueRequest', { requestId: msg.params.requestId });
  }
});
await c.navigate(`${BASE}/?date=2026-09-15`);
await c.waitFor(`document.querySelector('[data-testid=movies-error]')`);
results.push(check('AC-50 error text shown', (await c.evaluate(`document.querySelector('[data-testid=movies-error]').textContent.includes('Failed to load movies')`))));
results.push(check('AC-50 no cards on error', (await c.evaluate(q('[data-testid=movie-card]'))) === 0));
failing = false;
await c.evaluate(`document.querySelector('[data-testid=movies-retry-button]').click()`);
await c.waitFor(`document.querySelector('[data-testid=movie-card]')`);
results.push(check('AC-50 Retry re-issues request and loads', (await c.evaluate(q('[data-testid=movie-card]'))) === 5));
await c.send('Fetch.disable');

// Loading indicator while the movie request is held open.
failing = false;
await c.send('Fetch.enable', { patterns: [{ urlPattern: '*localhost:3000/movies*' }] });
let held = [];
c.listeners.length = 0;
c.listeners.push((msg) => {
  if (msg.method === 'Fetch.requestPaused') held.push(msg.params.requestId);
});
await c.navigate(`${BASE}/?date=2026-09-15`);
await sleep(400);
results.push(check('AC-49 loading indicator while in flight', (await c.evaluate(q('[data-testid=movies-loading]'))) === 1 && (await c.evaluate(q('[data-testid=movie-card]'))) === 0));
