  private readonly occupied = computed(() => new Set(this.screening()?.occupiedSeats ?? []));

  readonly showDate = computed(() => {
    const screening = this.screening();
    return screening ? formatShowDate(screening.date, screening.time) : '';
  });

  readonly rows = computed(() =>
    AUDITORIUM.map((row) => ({
      row: row.row,
      cells: row.cells.map((cell) => ({ cell, state: this.stateOf(cell) })),
    })),
  );

  constructor() {
    toObservable(this.id)
      .pipe(
        switchMap((id) =>
          this.api.screening(Number(id)).pipe(
            switchMap((screening) =>
              this.api.movie(screening.movieId).pipe(map((movie) => ({ screening, movie }))),
            ),
            catchError(() => {
              this.router.navigate(['/']);
              return EMPTY;
            }),
          ),
        ),
        takeUntilDestroyed(),
      )
      .subscribe(({ screening, movie }) => {
        this.screening.set(screening);
        this.movie.set(movie);
      });
  }

  private stateOf(cell: Cell): SeatState | null {
    if (cell.kind === 'aisle' || cell.kind === 'entrance') {
      return null;
    }
    if (cell.ids.some((id) => this.occupied().has(id))) {
      return 'unavailable';
    }
    return cell.accessible ? 'accessible' : 'available';
  }
