export type CellKind = 'seat' | 'couch' | 'aisle' | 'entrance';

export interface Cell {
  kind: CellKind;
  row: number;
  start: number;
  end: number;
  span: number;
  ids: string[];
  accessible: boolean;
}

export interface AuditoriumRow {
  row: number;
  cells: Cell[];
}

const ROW_COUNT = 15;
const COUCH_ROW = 15;
const ENTRANCE_LAST_ROW = 10;
const ACCESSIBLE_ROW = 1;
const ACCESSIBLE_FIRST_COLUMN = 10;
const ACCESSIBLE_LAST_COLUMN = 15;

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

function gap(row: number, kind: 'aisle' | 'entrance', span: number): Cell {
  return { kind, row, start: 0, end: 0, span, ids: [], accessible: false };
}

function block(row: number, from: number, to: number): Cell[] {
  const cells: Cell[] = [];
  for (let column = from; column <= to; ) {
    if (row === COUCH_ROW) {
      cells.push({
        kind: 'couch',
        row,
        start: column,
        end: column + 1,
        span: 2,
        ids: [seatId(row, column), seatId(row, column + 1)],
        accessible: false,
      });
      column += 2;
    } else {
      cells.push({
        kind: 'seat',
        row,
        start: column,
        end: column,
        span: 1,
        ids: [seatId(row, column)],
        accessible: row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN,
      });
      column += 1;
    }
  }
  return cells;
}

export const AUDITORIUM: AuditoriumRow[] = Array.from({ length: ROW_COUNT }, (_, index) => {
  const row = index + 1;
  const leftBlock = row <= ENTRANCE_LAST_ROW ? [gap(row, 'entrance', 4)] : block(row, 1, 4);
  return {
    row,
    cells: [
      ...leftBlock,
      gap(row, 'aisle', 2),
      ...block(row, 5, 20),
      gap(row, 'aisle', 2),
      ...block(row, 21, 24),
    ],
  };
});

import { Component, computed, inject, input, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { Router } from '@angular/router';
import { EMPTY, catchError, map, switchMap } from 'rxjs';
import { CinemaApi } from '../api';
import { formatShowDate } from '../dates';
import { Movie, Screening } from '../models';
import { AUDITORIUM, Cell } from './auditorium';

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

@Component({
  selector: 'app-seat-selection',
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  readonly id = input.required<string>();

  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);

  readonly screening = signal<Screening | null>(null);
  readonly movie = signal<Movie | null>(null);

  private readonly occupied = computed(() => new Set(this.screening()?.occupiedSeats ?? []));

  readonly showDate = computed(() => {
    const screening = this.screening();
    return screening ? formatShowDate(screening.date, screening.time) : '';
  });

  readonly rows = computed(() =>
    AUDITORIUM.map((row) => ({
      row: row.row,
      cells: row.cells.map((cell) => ({ cell, state: this.stateOf(cell) })),
    })),
  );

  constructor() {
    toObservable(this.id)
      .pipe(
        switchMap((id) =>
          this.api.screening(Number(id)).pipe(
            switchMap((screening) =>
              this.api.movie(screening.movieId).pipe(map((movie) => ({ screening, movie }))),
            ),
            catchError(() => {
              this.router.navigate(['/']);
              return EMPTY;
            }),
          ),
        ),
        takeUntilDestroyed(),
      )
      .subscribe(({ screening, movie }) => {
        this.screening.set(screening);
        this.movie.set(movie);
      });
  }

  private stateOf(cell: Cell): SeatState | null {
    if (cell.kind === 'aisle' || cell.kind === 'entrance') {
      return null;
    }
    if (cell.ids.some((id) => this.occupied().has(id))) {
      return 'unavailable';
    }
    return cell.accessible ? 'accessible' : 'available';
  }
}

