5	export async function connect() {
6	  const base = 'http://127.0.0.1:' + (process.env.CDP_PORT || 9222);
7	  const page = await (await fetch(`${base}/json/new?about:blank`, { method: 'PUT' })).json();
8	  const ws = new WebSocket(page.webSocketDebuggerUrl);
9	  await new Promise((res, rej) => {
10	    ws.onopen = res;
11	    ws.onerror = rej;
12	  });
13	  let id = 0;
14	  const pending = new Map();
15	  const listeners = [];
16	  ws.onmessage = (ev) => {
17	    const msg = JSON.parse(ev.data);
18	    if (msg.id && pending.has(msg.id)) {
19	      pending.get(msg.id)(msg);
20	      pending.delete(msg.id);
21	    } else if (msg.method) {
22	      listeners.forEach((l) => l(msg));
23	    }
24	  };
25	  const send = (method, params = {}) =>
26	    new Promise((resolve) => {
27	      const reqId = ++id;
28	      pending.set(reqId, resolve);
29	      ws.send(JSON.stringify({ id: reqId, method, params }));
30	    });
31	
32	  await send('Page.enable');
33	  await send('Runtime.enable');
34	  await send('Network.enable');
35	  // The sandbox has no internet; the render-blocking Google Fonts stylesheet would hang the page.
36	  await send('Network.setBlockedURLs', { urls: ['*fonts.googleapis.com*', '*fonts.gstatic.com*'] });
37	  await send('Emulation.setDeviceMetricsOverride', {
38	    width: 1280,
39	    height: 720,
40	    deviceScaleFactor: 1,
41	    mobile: false,
42	  });
43	  // Pin the browser clock to a date before the screenings so the day logic has data.
44	  await send('Page.addScriptToEvaluateOnNewDocument', {
45	    source: `(() => { const FIXED = new Date('${FIXED_NOW}').getTime(); const Real = Date;
46	      class FakeDate extends Real { constructor(...a) { if (a.length === 0) super(FIXED); else super(...a); }
47	        static now() { return FIXED; } }
48	      window.Date = FakeDate; })();`,
49	  });
50	
51	  const evaluate = async (expression) => {
52	    const res = await send('Runtime.evaluate', {
53	      expression,
54	      awaitPromise: true,
55	      returnByValue: true,
56	    });
57	    if (res.result.exceptionDetails) {
58	      throw new Error(JSON.stringify(res.result.exceptionDetails).slice(0, 500));
59	    }
60	    return res.result.result.value;
61	  };
62	
63	  const navigate = async (url) => {
64	    await send('Page.navigate', { url });
65	    await waitFor(`document.readyState === 'complete'`);
66	    await sleep(600);
67	  };
68	
69	  const waitFor = async (expression, timeout = 8000) => {
70	    const start = Date.now();
71	    while (Date.now() - start < timeout) {
72	      try {
73	        if (await evaluate(`Boolean(${expression})`)) return true;
74	      } catch {}
75	      await sleep(100);
76	    }
77	    throw new Error(`timed out waiting for: ${expression}`);
78	  };
79	
80	  const screenshot = async (path) => {
81	    const res = await send('Page.captureScreenshot', { format: 'png' });
82	    writeFileSync(path, Buffer.from(res.result.data, 'base64'));
83	  };
84	
85	  const close = async () => {
86	    ws.close();
87	    await fetch(`${base}/json/close/${page.id}`).catch(() => {});
88	  };
89	  return { send, evaluate, navigate, waitFor, screenshot, close, listeners };
90	}
