results.push(check('messages wait for blur', (await errorCount()) === 0));
await blur('first-name-input');
results.push(check('AC-42 first name shorter than 2', (await errorOf('first-name-error')) === 'First name must be at least 2 characters', String(await errorOf('first-name-error'))));
await setInput('first-name-input', 'Al');
results.push(check('message updates as value changes', (await errorOf('first-name-error')) === null));
await setInput('first-name-input', '');
results.push(check('AC-42 empty first name is required', (await errorOf('first-name-error')) === 'First name is required', String(await errorOf('first-name-error'))));
await setInput('last-name-input', 'K');
await blur('last-name-input');
results.push(check('AC-42 last name shorter than 2', (await errorOf('last-name-error')) === 'Last name must be at least 2 characters'));
await setInput('last-name-input', '');
results.push(check('AC-42 empty last name is required', (await errorOf('last-name-error')) === 'Last name is required'));

for (const bad of ['not-an-email', 'a@b', 'a@.com', 'a b@c.com']) {
  await setInput('email-input', bad);
