}
await setInput('email-input', 'anna.kowalska@example.com');
results.push(check('AC-43 valid email accepted', (await errorOf('email-error')) === null));
await setInput('email-input', '');
results.push(check('AC-43 empty email is required', (await errorOf('email-error')) === 'Email is required'));
await setInput('email-input', 'anna.kowalska@example.com');

await setInput('confirm-email-input', 'anna.kowalska@example.co');
await blur('confirm-email-input');
results.push(check('AC-43 confirm must match', (await errorOf('confirm-email-error')) === 'Email addresses do not match'));
await setInput('confirm-email-input', '');
results.push(check('AC-43 empty confirm is required', (await errorOf('confirm-email-error')) === 'Confirm email is required'));
await setInput('confirm-email-input', 'anna.kowalska@example.com');
results.push(check('AC-43 matching confirm accepted', (await errorOf('confirm-email-error')) === null));
await setInput('email-input', 'other@example.com');
results.push(check('confirm re-checked when email changes', (await errorOf('confirm-email-error')) === 'Email addresses do not match'));
await setInput('email-input', 'anna.kowalska@example.com');
results.push(check('confirm clears when email matches again', (await errorOf('confirm-email-error')) === null));

for (const bad of ['12345678', '12345678a', '1234567890']) {
  await setInput('phone-input', bad);
  await blur('phone-input');
  results.push(check(`AC-44 invalid phone "${bad}"`, (await errorOf('phone-error')) === 'Phone number must be exactly 9 digits'));
}
await setInput('phone-input', '');
results.push(check('AC-44 phone is optional when empty', (await errorOf('phone-error')) === null));
await setInput('phone-input', '123456789');
results.push(check('AC-44 nine digits accepted', (await errorOf('phone-error')) === null));
await setInput('phone-input', '12345678');
await blur('phone-input');

await click(sel('terms-checkbox'));
results.push(check('AC-45 terms checked, no message', (await isChecked('terms-checkbox')) === true && (await errorOf('terms-error')) === null));
await click(sel('terms-checkbox'));
results.push(check('AC-45 terms unchecked shows message after toggling', (await errorOf('terms-error')) === 'You must accept the terms and conditions'));

// Invalid form on pay (AC-46).
await click(sel('pay-button'));
await sleep(300);
results.push(check('AC-46 first name required shown on pay', (await errorOf('first-name-error')) === 'First name is required'));
results.push(check('AC-46 last name required shown on pay', (await errorOf('last-name-error')) === 'Last name is required'));
results.push(check('AC-46 phone message shown on pay', (await errorOf('phone-error')) === 'Phone number must be exactly 9 digits'));
results.push(check('AC-46 terms message shown on pay', (await errorOf('terms-error')) === 'You must accept the terms and conditions'));
results.push(check('AC-46 invalid toast', (await toastText()) === 'The form contains errors', String(await toastText())));
results.push(check('AC-46 stays on checkout', (await path()) === '/screenings/1/checkout'));
await c.screenshot('/tmp/e2e/t05-errors.png');

// Restored values show no messages after reload (7.1).
