results.push(check('7.1 reload restores value', (await valueOf('first-name-input')) === 'A'));
results.push(check('7.1 reload shows no messages', (await errorCount()) === 0));

// Valid form; values persist through Back, Confirm and reload (AC-63, AC-64).
await setInput('first-name-input', 'Anna');
await setInput('last-name-input', 'Kowalska');
await setInput('email-input', 'anna.kowalska@example.com');
await setInput('confirm-email-input', 'anna.kowalska@example.com');
await setInput('phone-input', '123456789');
