await c.navigate(checkoutUrl);
await waitCheckout();
results.push(check('AC-64 values survive reload', (await valueOf('last-name-input')) === 'Kowalska' && (await valueOf('phone-input')) === '123456789' && (await isChecked('terms-checkbox')) === true));

// Failed request: pay button in flight, error toast, form kept (AC-47).
await c.evaluate(INSTALL);
await c.evaluate(`window.__fail = true; window.__delay = 700`);
await click(sel('pay-button'));
await sleep(150);
results.push(check('AC-47 pay disabled and Processing… in flight', (await payDisabled()) === true && (await payText()) === 'Processing…', String(await payText())));
