results.push(check('AC-47 pay enabled again after failure', (await payDisabled()) === false && (await payText()) === 'Pay 64.00 PLN'));

// Successful request (AC-47).
await c.evaluate(`window.__fail = false; window.__delay = 0`);
await click(sel('pay-button'));
await waitPath('/confirmation');
results.push(check('AC-47 success navigates to /confirmation', (await path()) === '/confirmation'));
