results.push(check('reservation customer', JSON.stringify(body.customer) === JSON.stringify({ firstName: 'Anna', lastName: 'Kowalska', email: 'anna.kowalska@example.com', phone: '123456789' }), JSON.stringify(body.customer)));
results.push(check('booking becomes paid with email', (await bookingObj())?.paidEmail === 'anna.kowalska@example.com'));

// Paid booking no longer opens the checkout or summary (3.1).
await c.navigate(checkoutUrl);
await sleep(300);
results.push(check('guard: paid booking redirects checkout to /', (await path()) === '/'));
await c.navigate(summaryUrl);
await sleep(300);
results.push(check('guard: paid booking redirects summary to /', (await path()) === '/'));

// Seat map after payment starts a new booking with an empty form.
await c.navigate(seatsUrl);
await waitSeats();
results.push(check('new booking after payment is empty', (await countText()) === 'Selected seats: 0'));
await click(seatSel(5, 10));
await click('[data-testid=continue-button]');
await waitPath('/screenings/1/summary');
await waitSummary();
await click('[data-testid=confirm-button]');
await waitPath('/screenings/1/checkout');
await waitCheckout();
results.push(check('new booking form is empty', (await valueOf('first-name-input')) === '' && (await isChecked('terms-checkbox')) === false && (await errorCount()) === 0));
results.push(check('new booking pay label', (await payText()) === 'Pay 25.00 PLN', String(await payText())));

const failed = results.filter((r) => !r).length;
console.log(`${results.length - failed}/${results.length} passed`);
await c.close();
process.exit(failed ? 1 : 0);

