constructor() {
  toObservable(this.id)
    .pipe(
      switchMap((id) =>
        this.api.screeningWithMovie(Number(id)).pipe(
          catchError(() => {
            this.router.navigate(['/']);
            return EMPTY;
          }),
        ),
      ),
      takeUntilDestroyed(),
    )
    .subscribe(({ screening, movie }) => {
      this.screening.set(screening);
      this.movie.set(movie);
    });
}

