const setInput = (id, v) =>
  c.evaluate(`(() => { const el = document.querySelector(${JSON.stringify(sel(id))}); el.focus(); el.value = ${JSON.stringify(v)}; el.dispatchEvent(new Event('input', { bubbles: true })); })()`);
const blur = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).dispatchEvent(new Event('blur'))`);
const valueOf = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).value`);
const isChecked = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).checked`);
const errorOf = (id) => text(sel(id));
