  justify-content: flex-end;
  gap: 12px;
  margin-top: 24px;
}

import { Routes } from '@angular/router';
import { bookingInProgress } from './booking/booking';
import { Checkout } from './checkout/checkout';
import { MovieList } from './movie-list/movie-list';
import { Placeholder } from './placeholder';
import { SeatSelection } from './seat-selection/seat-selection';
import { Summary } from './summary/summary';

export const appRoutes: Routes = [
  { path: '', pathMatch: 'full', component: MovieList },
  { path: 'screenings/:id/seats', component: SeatSelection },
  { path: 'screenings/:id/summary', component: Summary, canActivate: [bookingInProgress] },
  { path: 'screenings/:id/checkout', component: Checkout, canActivate: [bookingInProgress] },
  { path: 'confirmation', component: Placeholder },
  { path: '**', redirectTo: '' },
];

import { connect, check, sleep } from './cdp.mjs';

const BASE = 'http://localhost:4200';
const results = [];
const c = await connect();
const sel = (id) => `[data-testid="${id}"]`;
const seatSel = (r, col) => `[data-testid=seat][data-row="${r}"][data-column="${col}"]`;
const click = (s) => c.evaluate(`document.querySelector(${JSON.stringify(s)}).click()`);
const text = (s) => c.evaluate(`document.querySelector(${JSON.stringify(s)})?.textContent.trim() ?? null`);
const countText = () => text('[data-testid=selected-seats-count]');
const path = () => c.evaluate(`location.pathname`);
const bookingObj = async () => JSON.parse((await c.evaluate(`sessionStorage.getItem('cinescope.booking')`)) ?? 'null');
const setInput = (id, v) =>
  c.evaluate(`(() => { const el = document.querySelector(${JSON.stringify(sel(id))}); el.focus(); el.value = ${JSON.stringify(v)}; el.dispatchEvent(new Event('input', { bubbles: true })); })()`);
const blur = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).dispatchEvent(new Event('blur'))`);
const valueOf = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).value`);
const isChecked = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).checked`);
const errorOf = (id) => text(sel(id));
const errorCount = () => c.evaluate(`document.querySelectorAll('[data-testid$="-error"]').length`);
const payDisabled = () => c.evaluate(`document.querySelector('[data-testid="pay-button"]').disabled`);
const payText = () => text(sel('pay-button'));
const toastText = () => text(sel('toast'));
const itemCount = () => c.evaluate(`document.querySelectorAll('[data-testid=summary-item]').length`);
const waitSeats = () => c.waitFor(`document.querySelector('[data-testid=seat-row]')`);
const waitSummary = () => c.waitFor(`document.querySelector('[data-testid=summary-title]')`);
const waitCheckout = () => c.waitFor(`document.querySelector('[data-testid=checkout-title]')`);
const waitPath = (p) => c.waitFor(`location.pathname === ${JSON.stringify(p)}`);
const reset = async () => {
  await c.navigate(`${BASE}/`);
  await c.evaluate(`sessionStorage.clear()`);
};
const checkoutUrl = `${BASE}/screenings/1/checkout`;
const summaryUrl = `${BASE}/screenings/1/summary`;
const seatsUrl = `${BASE}/screenings/1/seats`;

const INSTALL = `(() => {
  if (window.__hooked) return;
  window.__hooked = true; window.__posts = []; window.__fail = false; window.__delay = 0;
  const proto = XMLHttpRequest.prototype; const open = proto.open; const send = proto.send;
  proto.open = function (method, url, ...rest) {
    this.__reservation = method === 'POST' && String(url).endsWith('/reservations');
    if (this.__reservation && window.__fail) url = 'http://localhost:3999/reservations';
    return open.call(this, method, url, ...rest);
  };
  proto.send = function (body) {
    if (!this.__reservation) return send.call(this, body);
    window.__posts.push(body);
    if (window.__delay) { const xhr = this; setTimeout(() => send.call(xhr, body), window.__delay); return; }
    return send.call(this, body);
  };
})()`;

// Fresh booking: two seats, Row 5 (25 PLN) and Row 11 (39 PLN) = 64.00 PLN.
await reset();
await c.navigate(seatsUrl);
await waitSeats();
await click(seatSel(5, 10));
await click(seatSel(11, 10));
await click('[data-testid=continue-button]');
await waitPath('/screenings/1/summary');
await waitSummary();
await click('[data-testid=confirm-button]');
await waitPath('/screenings/1/checkout');
await waitCheckout();

results.push(check('AC-61 checkout title', (await text(sel('checkout-title'))) === 'Your details'));
const fieldIds = ['first-name-input', 'last-name-input', 'email-input', 'confirm-email-input', 'phone-input', 'terms-checkbox'];
const present = await c.evaluate(`[${fieldIds.map((id) => `'${id}'`).join(',')}].every((id) => document.querySelector('[data-testid="' + id + '"]'))`);
results.push(check('AC-41 all six fields rendered', present === true));
const labels = {
  'first-name-label': 'First name *',
