import { Component, computed, inject, input, signal } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { Router } from '@angular/router';
import { finalize } from 'rxjs';
import { CinemaApi } from '../api';
import { BookingService, CheckoutForm } from '../booking/booking';
import { formatPrice, totalPriceOf } from '../booking/pricing';
import { bookedCells } from '../seat-selection/auditorium';
import { Toaster } from '../toast/toast';

type TextField = 'firstName' | 'lastName' | 'email' | 'confirmEmail' | 'phone';
type Field = TextField | 'terms';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_PATTERN = /^\d{9}$/;

const NOT_TOUCHED: Record<Field, boolean> = {
  firstName: false,
  lastName: false,
  email: false,
  confirmEmail: false,
  phone: false,
  terms: false,
};

const ALL_TOUCHED: Record<Field, boolean> = {
  firstName: true,
  lastName: true,
  email: true,
  confirmEmail: true,
  phone: true,
  terms: true,
};

const EMPTY_FORM: CheckoutForm = {
  firstName: '',
  lastName: '',
  email: '',
  confirmEmail: '',
  phone: '',
  terms: false,
};

function nameError(value: string, label: string): string | null {
  if (!value) {
    return `${label} is required`;
  }
  return value.length < 2 ? `${label} must be at least 2 characters` : null;
}

function emailError(email: string): string | null {
  if (!email) {
    return 'Email is required';
  }
  return EMAIL_PATTERN.test(email) ? null : 'Enter a valid email address';
}

function confirmEmailError(confirmEmail: string, email: string): string | null {
  if (!confirmEmail) {
    return 'Confirm email is required';
  }
  return confirmEmail === email ? null : 'Email addresses do not match';
}

function phoneError(phone: string): string | null {
  if (!phone) {
    return null;
  }
  return PHONE_PATTERN.test(phone) ? null : 'Phone number must be exactly 9 digits';
}

@Component({
  selector: 'app-checkout',
  imports: [MatButtonModule, MatFormFieldModule, MatInputModule],
  templateUrl: './checkout.html',
  styleUrl: './checkout.scss',
})
export class Checkout {
  readonly id = input.required<string>();

  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly bookings = inject(BookingService);
  private readonly toaster = inject(Toaster);

  readonly seats = signal(this.bookings.current()?.seats ?? []);
  readonly form = signal<CheckoutForm>(this.bookings.current()?.checkout ?? EMPTY_FORM);
  readonly touched = signal<Record<Field, boolean>>(NOT_TOUCHED);
  readonly submitting = signal(false);

  readonly total = computed(() => totalPriceOf(this.seats()));
  readonly payLabel = computed(() => `Pay ${formatPrice(this.total())}`);

  private readonly errors = computed<Record<Field, string | null>>(() => {
    const form = this.form();
    return {
      firstName: nameError(form.firstName, 'First name'),
      lastName: nameError(form.lastName, 'Last name'),
      email: emailError(form.email),
      confirmEmail: confirmEmailError(form.confirmEmail, form.email),
      phone: phoneError(form.phone),
      terms: form.terms ? null : 'You must accept the terms and conditions',
    };
  });

  private readonly hasErrors = computed(() => Object.values(this.errors()).some((error) => error !== null));

  fieldError(field: Field): string | null {
    return this.touched()[field] ? this.errors()[field] : null;
  }

  touch(field: Field): void {
    this.touched.update((touched) => ({ ...touched, [field]: true }));
  }

  setText(field: TextField, event: Event): void {
    this.edit({ [field]: (event.target as HTMLInputElement).value });
  }

  setTerms(event: Event): void {
    this.edit({ terms: (event.target as HTMLInputElement).checked });
    this.touch('terms');
  }

  pay(): void {
    this.touched.set(ALL_TOUCHED);
    if (this.hasErrors()) {
      this.toaster.show('The form contains errors');
      return;
    }
    const booking = this.bookings.current();
    if (!booking) {
      return;
    }
    const form = this.form();
    this.submitting.set(true);
    this.api
      .createReservation({
        screeningId: booking.screeningId,
        seats: bookedCells(booking.seats).flatMap((cell) => cell.ids),
        customer: {
          firstName: form.firstName,
          lastName: form.lastName,
          email: form.email,
          phone: form.phone,
        },
        totalPrice: totalPriceOf(booking.seats),
      })
      .pipe(finalize(() => this.submitting.set(false)))
      .subscribe({
        next: () => {
          this.bookings.save({ ...booking, paidEmail: form.email });
          this.router.navigate(['/confirmation']);
        },
        error: () => this.toaster.show('Payment failed. Please try again.'),
      });
  }

  back(): void {
    this.router.navigate(['/screenings', this.id(), 'summary']);
  }

  private edit(change: Partial<CheckoutForm>): void {
    const form = { ...this.form(), ...change };
    this.form.set(form);
    const booking = this.bookings.current();
    if (booking) {
      this.bookings.save({ ...booking, checkout: form });
    }
  }
}

:host {
  display: block;
  max-width: 480px;
  margin: 0 auto;
  padding: 24px;
}

h1 {
  margin: 0 0 24px;
  font-size: 28px;
}

mat-form-field {
  display: block;
  width: 100%;
}

.field {
  margin-bottom: 8px;
}

.error {
  margin: 0;
  font-size: 13px;
  color: #c62828;
}

.terms {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 24px;
}

import { Routes } from '@angular/router';
import { bookingInProgress } from './booking/booking';
import { Checkout } from './checkout/checkout';
import { MovieList } from './movie-list/movie-list';
import { Placeholder } from './placeholder';
import { SeatSelection } from './seat-selection/seat-selection';
import { Summary } from './summary/summary';

export const appRoutes: Routes = [
  { path: '', pathMatch: 'full', component: MovieList },
  { path: 'screenings/:id/seats', component: SeatSelection },
  { path: 'screenings/:id/summary', component: Summary, canActivate: [bookingInProgress] },
  { path: 'screenings/:id/checkout', component: Checkout, canActivate: [bookingInProgress] },
  { path: 'confirmation', component: Placeholder },
  { path: '**', redirectTo: '' },
];

import { connect, check, sleep } from './cdp.mjs';

const BASE = 'http://localhost:4200';
const results = [];
const c = await connect();
const sel = (id) => `[data-testid="${id}"]`;
const seatSel = (r, col) => `[data-testid=seat][data-row="${r}"][data-column="${col}"]`;
const click = (s) => c.evaluate(`document.querySelector(${JSON.stringify(s)}).click()`);
const text = (s) => c.evaluate(`document.querySelector(${JSON.stringify(s)})?.textContent.trim() ?? null`);
const countText = () => text('[data-testid=selected-seats-count]');
const path = () => c.evaluate(`location.pathname`);
const bookingObj = async () => JSON.parse((await c.evaluate(`sessionStorage.getItem('cinescope.booking')`)) ?? 'null');
const setInput = (id, v) =>
  c.evaluate(`(() => { const el = document.querySelector(${JSON.stringify(sel(id))}); el.focus(); el.value = ${JSON.stringify(v)}; el.dispatchEvent(new Event('input', { bubbles: true })); })()`);
const blur = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).dispatchEvent(new Event('blur'))`);
const valueOf = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).value`);
const isChecked = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).checked`);
const errorOf = (id) => text(sel(id));
const errorCount = () => c.evaluate(`document.querySelectorAll('[data-testid$="-error"]').length`);
const payDisabled = () => c.evaluate(`document.querySelector('[data-testid="pay-button"]').disabled`);
const payText = () => text(sel('pay-button'));
const toastText = () => text(sel('toast'));
const itemCount = () => c.evaluate(`document.querySelectorAll('[data-testid=summary-item]').length`);
const waitSeats = () => c.waitFor(`document.querySelector('[data-testid=seat-row]')`);
const waitSummary = () => c.waitFor(`document.querySelector('[data-testid=summary-title]')`);
const waitCheckout = () => c.waitFor(`document.querySelector('[data-testid=checkout-title]')`);
const waitPath = (p) => c.waitFor(`location.pathname === ${JSON.stringify(p)}`);
const reset = async () => {
  await c.navigate(`${BASE}/`);
  await c.evaluate(`sessionStorage.clear()`);
};
const checkoutUrl = `${BASE}/screenings/1/checkout`;
const summaryUrl = `${BASE}/screenings/1/summary`;
const seatsUrl = `${BASE}/screenings/1/seats`;

const INSTALL = `(() => {
  if (window.__hooked) return;
  window.__hooked = true; window.__posts = []; window.__fail = false; window.__delay = 0;
  const proto = XMLHttpRequest.prototype; const open = proto.open; const send = proto.send;
  proto.open = function (method, url, ...rest) {
    this.__reservation = method === 'POST' && String(url).endsWith('/reservations');
    if (this.__reservation && window.__fail) url = 'http://localhost:3999/reservations';
    return open.call(this, method, url, ...rest);
  };
  proto.send = function (body) {
    if (!this.__reservation) return send.call(this, body);
    window.__posts.push(body);
    if (window.__delay) { const xhr = this; setTimeout(() => send.call(xhr, body), window.__delay); return; }
    return send.call(this, body);
  };
})()`;

// Fresh booking: two seats, Row 5 (25 PLN) and Row 11 (39 PLN) = 64.00 PLN.
await reset();
await c.navigate(seatsUrl);
await waitSeats();
await click(seatSel(5, 10));
await click(seatSel(11, 10));
await click('[data-testid=continue-button]');
await waitPath('/screenings/1/summary');
await waitSummary();
await click('[data-testid=confirm-button]');
await waitPath('/screenings/1/checkout');
await waitCheckout();

results.push(check('AC-61 checkout title', (await text(sel('checkout-title'))) === 'Your details'));
const fieldIds = ['first-name-input', 'last-name-input', 'email-input', 'confirm-email-input', 'phone-input', 'terms-checkbox'];
const present = await c.evaluate(`[${fieldIds.map((id) => `'${id}'`).join(',')}].every((id) => document.querySelector('[data-testid="' + id + '"]'))`);
results.push(check('AC-41 all six fields rendered', present === true));
const labels = {
  'first-name-label': 'First name *',
  'last-name-label': 'Last name *',
  'email-label': 'Email *',
  'confirm-email-label': 'Confirm email *',
  'phone-label': 'Phone number',
  'terms-label': 'I accept the terms and conditions *',
};
for (const [id, label] of Object.entries(labels)) {
  results.push(check(`AC-65 label ${id}`, (await text(sel(id))) === label, String(await text(sel(id)))));
}
results.push(check('AC-62 pay label', (await payText()) === 'Pay 64.00 PLN', String(await payText())));
results.push(check('AC-46 pay enabled initially', (await payDisabled()) === false));
results.push(check('no messages before any interaction', (await errorCount()) === 0));

// Validation timing and rules (AC-42..45).
await setInput('first-name-input', 'A');
results.push(check('messages wait for blur', (await errorCount()) === 0));
await blur('first-name-input');
results.push(check('AC-42 first name shorter than 2', (await errorOf('first-name-error')) === 'First name must be at least 2 characters', String(await errorOf('first-name-error'))));
await setInput('first-name-input', 'Al');
results.push(check('message updates as value changes', (await errorOf('first-name-error')) === null));
await setInput('first-name-input', '');
results.push(check('AC-42 empty first name is required', (await errorOf('first-name-error')) === 'First name is required', String(await errorOf('first-name-error'))));
await setInput('last-name-input', 'K');
await blur('last-name-input');
results.push(check('AC-42 last name shorter than 2', (await errorOf('last-name-error')) === 'Last name must be at least 2 characters'));
await setInput('last-name-input', '');
results.push(check('AC-42 empty last name is required', (await errorOf('last-name-error')) === 'Last name is required'));

for (const bad of ['not-an-email', 'a@b', 'a@.com', 'a b@c.com']) {
  await setInput('email-input', bad);
  await blur('email-input');
  results.push(check(`AC-43 invalid email "${bad}"`, (await errorOf('email-error')) === 'Enter a valid email address'));
}
await setInput('email-input', 'anna.kowalska@example.com');
