  window.__hooked = true; window.__posts = []; window.__fail = false; window.__delay = 0;
  const origFetch = window.fetch.bind(window);
  window.fetch = async (input, init) => {
    const request = input instanceof Request ? input : null;
    const url = request ? request.url : String(input);
    const method = (init?.method ?? request?.method ?? 'GET').toUpperCase();
    if (method !== 'POST' || !url.endsWith('/reservations')) return origFetch(input, init);
    window.__posts.push(request ? await request.clone().text() : init?.body);
    if (window.__delay) await new Promise((r) => setTimeout(r, window.__delay));
    if (window.__fail) throw new TypeError('Failed to fetch');
    return origFetch(input, init);
  };
})()`;

constructor() {
  toObservable(this.id)
    .pipe(
      switchMap((id) =>
        this.api.screeningWithMovie(Number(id)).pipe(
          catchError(() => {
            this.router.navigate(['/']);
            return EMPTY;
          }),
        ),
      ),
      takeUntilDestroyed(),
    )
    .subscribe(({ screening, movie }) => {
      this.screening.set(screening);
      this.movie.set(movie);
    });
}

