import { connect, check, sleep } from './cdp.mjs';

const BASE = 'http://localhost:4200';
const results = [];
const c = await connect();
const seatSel = (r, col) => `[data-testid=seat][data-row="${r}"][data-column="${col}"]`;
const couchSel = (r, start) => `[data-testid=couch][data-row="${r}"][data-column-start="${start}"]`;
const click = (sel) => c.evaluate(`document.querySelector(${JSON.stringify(sel)}).click()`);
const text = (sel) => c.evaluate(`document.querySelector(${JSON.stringify(sel)})?.textContent.trim() ?? null`);
const stateOf = (sel) => c.evaluate(`document.querySelector(${JSON.stringify(sel)}).dataset.state`);
const disabled = (sel) => c.evaluate(`document.querySelector(${JSON.stringify(sel)}).disabled`);
const path = () => c.evaluate(`location.pathname`);
const booking = () => c.evaluate(`sessionStorage.getItem('cinescope.booking')`);
const bookingSeats = async () => JSON.parse((await booking()) ?? '{}').seats ?? null;
const countText = () => text('[data-testid=selected-seats-count]');
const items = () => c.evaluate(`[...document.querySelectorAll('[data-testid=summary-item]')].map(li => ({
  title: li.querySelector('[data-testid=summary-item-title]').textContent.trim(),
  datetime: li.querySelector('[data-testid=summary-item-datetime]').textContent.trim(),
  row: li.querySelector('[data-testid=summary-item-row]').textContent.trim(),
  seat: li.querySelector('[data-testid=summary-item-seat]').textContent.trim(),
  price: li.querySelector('[data-testid=summary-item-price]').textContent.trim(),
  remove: Boolean(li.querySelector('[data-testid=summary-item-remove-button]')),
}))`);
const waitSeats = () => c.waitFor(`document.querySelector('[data-testid=seat-row]')`);
const waitSummary = () => c.waitFor(`document.querySelector('[data-testid=summary-title]')`);
const waitPath = (p) => c.waitFor(`location.pathname === ${JSON.stringify(p)}`);
const reset = async () => {
  await c.navigate(`${BASE}/`);
  await c.evaluate(`sessionStorage.clear()`);
};
const movieTitle = (await (await fetch('http://localhost:3000/movies/1')).json()).title;
const seatsUrl = `${BASE}/screenings/1/seats`;
const summaryUrl = `${BASE}/screenings/1/summary`;

// Cancel clears the booking and returns to the movie list (AC-33).
await reset();
await c.navigate(seatsUrl);
await waitSeats();
results.push(check('AC-35 continue disabled with no selection', (await disabled('[data-testid=continue-button]')) === true));
await click(seatSel(5, 10));
results.push(check('booking saved on seat click', JSON.stringify(await bookingSeats()) === JSON.stringify(['R5C10'])));
await click('[data-testid=cancel-button]');
await waitPath('/');
results.push(check('AC-33 cancel navigates to /', (await path()) === '/'));
results.push(check('AC-33 cancel clears booking', (await booking()) === null, String(await booking())));
await c.navigate(seatsUrl);
await waitSeats();
results.push(check('AC-33 selection cleared after cancel', (await countText()) === 'Selected seats: 0'));

// Main booking: covers every price tier, accessible, and a couch.
const picks = [seatSel(1, 12), seatSel(5, 10), seatSel(6, 10), seatSel(10, 10), seatSel(11, 10), seatSel(14, 10)];
for (const s of picks) await click(s);
await click(couchSel(15, 3));
results.push(check('8 seats selected (couch counts 2)', (await countText()) === 'Selected seats: 8'));
const showDate = (await text('[data-testid=seat-map-subtitle]')).replace('Show Date: ', '');
results.push(check('continue enabled with selection', (await disabled('[data-testid=continue-button]')) === false));

await click('[data-testid=continue-button]');
await waitPath('/screenings/1/summary');
results.push(check('AC-34 continue navigates to summary', (await path()) === '/screenings/1/summary'));
await waitSummary();
results.push(check('AC-59 summary title', (await text('[data-testid=summary-title]')) === 'Your tickets'));

const expected = [
  { row: '1', seat: '12', price: '25.00 PLN' },
  { row: '5', seat: '10', price: '25.00 PLN' },
  { row: '6', seat: '10', price: '32.00 PLN' },
  { row: '10', seat: '10', price: '32.00 PLN' },
  { row: '11', seat: '10', price: '39.00 PLN' },
  { row: '14', seat: '10', price: '39.00 PLN' },
  { row: '15', seat: 'Couch 3-4', price: '89.00 PLN' },
];
const got = await items();
results.push(check('AC-28..32,37 item count and rows/seats/prices', got.length === expected.length && expected.every((e, i) => got[i]?.row === e.row && got[i]?.seat === e.seat && got[i]?.price === e.price), JSON.stringify(got.map(({ row, seat, price }) => [row, seat, price]))));
results.push(check('AC-36 each item has movie title', got.every((i) => i.title === movieTitle), movieTitle));
results.push(check('AC-36 each item has screening date and time', got.every((i) => i.datetime === showDate), `${showDate} vs ${got[0]?.datetime}`));
results.push(check('AC-60 each item has Remove', got.every((i) => i.remove)));
results.push(check('AC-38 total equals sum of prices', (await text('[data-testid=summary-total]')) === 'Total: 281.00 PLN', await text('[data-testid=summary-total]')));
await c.screenshot('/tmp/e2e/t04-summary.png');

// Reload keeps the summary (reload survival).
await c.navigate(summaryUrl);
await waitSummary();
results.push(check('reload summary keeps 7 items and total', (await items()).length === 7 && (await text('[data-testid=summary-total]')) === 'Total: 281.00 PLN'));

// Back returns to the seat map with the selection intact (AC-39).
await click('[data-testid=back-button]');
await waitPath('/screenings/1/seats');
await waitSeats();
results.push(check('AC-39 back shows 8 selected seats', (await countText()) === 'Selected seats: 8'));
results.push(check('AC-39 back keeps seat states', (await stateOf(seatSel(14, 10))) === 'selected' && (await stateOf(couchSel(15, 3))) === 'selected' && (await stateOf(seatSel(1, 12))) === 'selected'));
await c.navigate(seatsUrl);
await waitSeats();
results.push(check('reload seat map keeps 8 selected seats', (await countText()) === 'Selected seats: 8' && (await stateOf(couchSel(15, 3))) === 'selected'));

// Confirm navigates to checkout (AC-40).
await click('[data-testid=continue-button]');
await waitPath('/screenings/1/summary');
await waitSummary();
await click('[data-testid=confirm-button]');
await waitPath('/screenings/1/checkout');
results.push(check('AC-40 confirm navigates to checkout', (await path()) === '/screenings/1/checkout'));

// Remove the couch, then the first seat (AC-60 total updates).
await c.navigate(summaryUrl);
await waitSummary();
await c.evaluate(`document.querySelectorAll('[data-testid=summary-item-remove-button]')[6].click()`);
await c.waitFor(`document.querySelectorAll('[data-testid=summary-item]').length === 6`);
results.push(check('AC-60 remove couch updates total', (await text('[data-testid=summary-total]')) === 'Total: 192.00 PLN', await text('[data-testid=summary-total]')));
results.push(check('AC-60 remove couch drops couch ids from booking', JSON.stringify(await bookingSeats()) === JSON.stringify(['R1C12', 'R5C10', 'R6C10', 'R10C10', 'R11C10', 'R14C10'])));
await c.evaluate(`document.querySelectorAll('[data-testid=summary-item-remove-button]')[0].click()`);
await c.waitFor(`document.querySelectorAll('[data-testid=summary-item]').length === 5`);
results.push(check('AC-60 remove seat updates total', (await text('[data-testid=summary-total]')) === 'Total: 167.00 PLN', await text('[data-testid=summary-total]')));
await click('[data-testid=back-button]');
await waitPath('/screenings/1/seats');
await waitSeats();
results.push(check('removed seats are no longer selected on seat map', (await countText()) === 'Selected seats: 5' && (await stateOf(couchSel(15, 3))) === 'available' && (await stateOf(seatSel(1, 12))) === 'accessible'));

// Removing the last item returns to the seat map.
await click('[data-testid=continue-button]');
await waitPath('/screenings/1/summary');
await waitSummary();
for (let i = 0; i < 5; i++) {
  await c.evaluate(`document.querySelector('[data-testid=summary-item-remove-button]')?.click()`);
  await sleep(250);
}
await waitPath('/screenings/1/seats');
await waitSeats();
results.push(check('AC-60 removing last item returns to seat map', (await path()) === '/screenings/1/seats'));
results.push(check('AC-35 continue disabled after emptying', (await countText()) === 'Selected seats: 0' && (await disabled('[data-testid=continue-button]')) === true));

// Guards: no booking, mismatched booking, or empty booking redirect to /.
await reset();
await c.navigate(summaryUrl);
await sleep(300);
results.push(check('guard: summary without booking redirects to /', (await path()) === '/'));
await reset();
await c.navigate(`${BASE}/screenings/1/checkout`);
await sleep(300);
results.push(check('guard: checkout without booking redirects to /', (await path()) === '/'));
await c.navigate(`${BASE}/`);
await c.evaluate(`sessionStorage.setItem('cinescope.booking', JSON.stringify({ screeningId: 2, seats: ['R5C10'] }))`);
await c.navigate(summaryUrl);
await sleep(300);
results.push(check('guard: booking for another screening redirects to /', (await path()) === '/'));
await c.navigate(`${BASE}/`);
await c.evaluate(`sessionStorage.setItem('cinescope.booking', JSON.stringify({ screeningId: 1, seats: [] }))`);
await c.navigate(summaryUrl);
await sleep(300);
results.push(check('guard: empty booking redirects to /', (await path()) === '/'));
await c.navigate(`${BASE}/`);
await c.evaluate(`sessionStorage.setItem('cinescope.booking', JSON.stringify({ screeningId: 1, seats: ['R5C10'] }))`);
await c.navigate(summaryUrl);
await waitSummary();
results.push(check('guard: matching booking allows summary', (await path()) === '/screenings/1/summary' && (await items()).length === 1));
await c.navigate(`${BASE}/screenings/1/checkout`);
await sleep(300);
results.push(check('guard: matching booking allows checkout', (await path()) === '/screenings/1/checkout'));

const failed = results.filter((r) => !r).length;
console.log(`${results.length - failed}/${results.length} passed`);
await c.close();
process.exit(failed ? 1 : 0);

