import { connect, check, sleep } from './cdp.mjs';

const BASE = 'http://localhost:4200';
const results = [];
const c = await connect();
const seatSel = (r, col) => `[data-testid=seat][data-row="${r}"][data-column="${col}"]`;
const couchSel = (r, start) => `[data-testid=couch][data-row="${r}"][data-column-start="${start}"]`;
const click = (sel) => c.evaluate(`document.querySelector(${JSON.stringify(sel)}).click()`);
const state = (sel) => c.evaluate(`document.querySelector(${JSON.stringify(sel)}).dataset.state`);
const countText = () => c.evaluate(`document.querySelector('[data-testid=selected-seats-count]').textContent.trim()`);
const rowLines = () => c.evaluate(`[...document.querySelectorAll('[data-testid=selected-seats-row]')].map(e => e.textContent.trim())`);
const toastCount = () => c.evaluate(`document.querySelectorAll('[data-testid=toast]').length`);
const toastText = () => c.evaluate(`document.querySelector('[data-testid=toast]')?.textContent.trim() ?? null`);

await c.navigate(`${BASE}/screenings/1/seats`);
await c.waitFor(`document.querySelector('[data-testid=seat-row]')`);

results.push(check('AC-58 empty panel', (await countText()) === 'Selected seats: 0' && (await rowLines()).length === 0));

await click(seatSel(5, 10));
results.push(check('AC-18 click selects seat', (await state(seatSel(5, 10))) === 'selected'));
const selBg = await c.evaluate(`getComputedStyle(document.querySelector(${JSON.stringify(seatSel(5, 10))})).backgroundColor`);
results.push(check('AC-25 selected colour #F9A825', selBg === 'rgb(249, 168, 37)', selBg));
results.push(check('AC-58 panel count 1 and row line', (await countText()) === 'Selected seats: 1' && JSON.stringify(await rowLines()) === JSON.stringify(['Row 5: 10'])));
await click(seatSel(5, 10));
results.push(check('AC-18 second click deselects', (await state(seatSel(5, 10))) === 'available' && (await countText()) === 'Selected seats: 0'));

await click(seatSel(3, 7));
results.push(check('AC-16 unavailable seat cannot be selected', (await state(seatSel(3, 7))) === 'unavailable' && (await countText()) === 'Selected seats: 0'));
await click(couchSel(15, 5));
results.push(check('AC-17 unavailable couch cannot be selected', (await state(couchSel(15, 5))) === 'unavailable' && (await countText()) === 'Selected seats: 0'));

await click(couchSel(15, 1));
results.push(check('AC-19 couch selects as one unit', (await state(couchSel(15, 1))) === 'selected' && (await countText()) === 'Selected seats: 2'));
results.push(check('couch row line', JSON.stringify(await rowLines()) === JSON.stringify(['Row 15: 1-2'])));
await click(couchSel(15, 1));
results.push(check('couch deselects as a unit', (await state(couchSel(15, 1))) === 'available' && (await countText()) === 'Selected seats: 0'));

await click(seatSel(1, 12));
results.push(check('accessible seat selectable', (await state(seatSel(1, 12))) === 'selected'));
await click(seatSel(1, 12));
results.push(check('accessible seat deselects back to accessible', (await state(seatSel(1, 12))) === 'accessible'));

// Ordering and grouping in the panel.
await click(seatSel(7, 12));
await click(seatSel(7, 11));
await click(couchSel(15, 3));
