107	    if (!screening || !isSeatLike(cell) || cell.ids.some((id) => this.occupied().has(id))) {
108	      return;
109	    }
110	    const selected = this.selected();
111	    const deselect = cell.ids.every((id) => selected.has(id));
112	    if (!deselect && selected.size + cell.ids.length > MAX_SEATS) {
113	      this.toaster.show('Maximum 10 seats per booking');
114	      return;
115	    }
116	    const seats = deselect
117	      ? [...selected].filter((id) => !cell.ids.includes(id))
118	      : [...selected, ...cell.ids];
