  if (window.__hooked) return;
  window.__hooked = true; window.__posts = []; window.__fail = false; window.__delay = 0;
  const proto = XMLHttpRequest.prototype; const open = proto.open; const send = proto.send;
  proto.open = function (method, url, ...rest) {
    this.__reservation = method === 'POST' && String(url).endsWith('/reservations');
    if (this.__reservation && window.__fail) url = 'http://localhost:3999/reservations';
    return open.call(this, method, url, ...rest);
  };
  proto.send = function (body) {
    if (!this.__reservation) return send.call(this, body);
    window.__posts.push(body);
    if (window.__delay) { const xhr = this; setTimeout(() => send.call(xhr, body), window.__delay); return; }
    return send.call(this, body);
