await click(sel('terms-checkbox'));
results.push(check('AC-45 terms checked, no message', (await isChecked('terms-checkbox')) === true && (await errorOf('terms-error')) === null));
await click(sel('terms-checkbox'));
results.push(check('AC-45 terms unchecked shows message after toggling', (await errorOf('terms-error')) === 'You must accept the terms and conditions'));

// Invalid form on pay (AC-46).
