results.push(check('AC-46 first name required shown on pay', (await errorOf('first-name-error')) === 'First name is required'));
results.push(check('AC-46 last name required shown on pay', (await errorOf('last-name-error')) === 'Last name is required'));
results.push(check('AC-46 phone message shown on pay', (await errorOf('phone-error')) === 'Phone number must be exactly 9 digits'));
results.push(check('AC-46 terms message shown on pay', (await errorOf('terms-error')) === 'You must accept the terms and conditions'));
results.push(check('AC-46 invalid toast', (await toastText()) === 'The form contains errors', String(await toastText())));
results.push(check('AC-46 stays on checkout', (await path()) === '/screenings/1/checkout'));
await c.screenshot('/tmp/e2e/t05-errors.png');

// Restored values show no messages after reload (7.1).
