import { Component, inject } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { Router } from '@angular/router';
import { BookingService } from '../booking/booking';

@Component({
  selector: 'app-confirmation',
  imports: [MatButtonModule],
  templateUrl: './confirmation.html',
  styleUrl: './confirmation.scss',
})
export class Confirmation {
  private readonly router = inject(Router);
  private readonly bookings = inject(BookingService);

  readonly email = this.bookings.current()?.paidEmail ?? '';

  continue(): void {
    this.bookings.clear();
    this.router.navigate(['/']);
  }
}

:host {
  display: block;
  max-width: 480px;
  margin: 0 auto;
  padding: 24px;
  text-align: center;
}

h1 {
  margin: 0 0 16px;
  font-size: 28px;
}

.message {
  margin: 0 0 24px;
  font-size: 16px;
}

.actions {
  display: flex;
  justify-content: center;
}

import { Routes } from '@angular/router';
import { bookingInProgress, bookingPaid } from './booking/booking';
import { Checkout } from './checkout/checkout';
import { Confirmation } from './confirmation/confirmation';
import { MovieList } from './movie-list/movie-list';
import { SeatSelection } from './seat-selection/seat-selection';
import { Summary } from './summary/summary';

export const appRoutes: Routes = [
  { path: '', pathMatch: 'full', component: MovieList },
  { path: 'screenings/:id/seats', component: SeatSelection },
  { path: 'screenings/:id/summary', component: Summary, canActivate: [bookingInProgress] },
  { path: 'screenings/:id/checkout', component: Checkout, canActivate: [bookingInProgress] },
  { path: 'confirmation', component: Confirmation, canActivate: [bookingPaid] },
  { path: '**', redirectTo: '' },
];

import { connect, check, sleep } from './cdp.mjs';

const BASE = 'http://localhost:4200';
const results = [];
const c = await connect();
const sel = (id) => `[data-testid="${id}"]`;
const seatSel = (r, col) => `[data-testid=seat][data-row="${r}"][data-column="${col}"]`;
const click = (s) => c.evaluate(`document.querySelector(${JSON.stringify(s)}).click()`);
const text = (s) => c.evaluate(`document.querySelector(${JSON.stringify(s)})?.textContent.trim() ?? null`);
const countText = () => text('[data-testid=selected-seats-count]');
const path = () => c.evaluate(`location.pathname`);
const booking = () => c.evaluate(`sessionStorage.getItem('cinescope.booking')`);
const setInput = (id, v) =>
  c.evaluate(`(() => { const el = document.querySelector(${JSON.stringify(sel(id))}); el.focus(); el.value = ${JSON.stringify(v)}; el.dispatchEvent(new Event('input', { bubbles: true })); })()`);
const valueOf = (id) => c.evaluate(`document.querySelector(${JSON.stringify(sel(id))}).value`);
const waitSeats = () => c.waitFor(`document.querySelector('[data-testid=seat-row]')`);
const waitSummary = () => c.waitFor(`document.querySelector('[data-testid=summary-title]')`);
const waitCheckout = () => c.waitFor(`document.querySelector('[data-testid=checkout-title]')`);
const waitConfirmation = () => c.waitFor(`document.querySelector('[data-testid=confirmation-heading]')`);
const waitPath = (p) => c.waitFor(`location.pathname === ${JSON.stringify(p)}`);
const reset = async () => {
  await c.navigate(`${BASE}/`);
  await c.evaluate(`sessionStorage.clear()`);
};
const confirmationUrl = `${BASE}/confirmation`;
const EMAIL = 'anna.kowalska@example.com';

// Guard: confirmation needs a paid booking.
await reset();
await c.navigate(confirmationUrl);
await sleep(300);
results.push(check('AC-48 guard: no booking redirects /confirmation to /', (await path()) === '/'));

await c.navigate(`${BASE}/`);
await c.evaluate(`sessionStorage.setItem('cinescope.booking', JSON.stringify({ screeningId: 1, seats: ['R5C10'] }))`);
await c.navigate(confirmationUrl);
await sleep(300);
results.push(check('AC-48 guard: unpaid booking redirects /confirmation to /', (await path()) === '/'));

// Real payment flow to the confirmation.
await reset();
await c.navigate(`${BASE}/screenings/1/seats`);
await waitSeats();
await click(seatSel(5, 10));
await click('[data-testid=continue-button]');
await waitPath('/screenings/1/summary');
await waitSummary();
await click('[data-testid=confirm-button]');
await waitPath('/screenings/1/checkout');
await waitCheckout();
await setInput('first-name-input', 'Anna');
await setInput('last-name-input', 'Kowalska');
await setInput('email-input', EMAIL);
await setInput('confirm-email-input', EMAIL);
await click(sel('terms-checkbox'));
await click(sel('pay-button'));
await waitPath('/confirmation');
await waitConfirmation();

results.push(check('AC-48 heading', (await text(sel('confirmation-heading'))) === 'Payment successful'));
results.push(check('AC-48 message with email', (await text(sel('confirmation-message'))) === `Your tickets will be sent shortly to ${EMAIL}`, String(await text(sel('confirmation-message')))));
results.push(check('AC-48 booking holds paid email', JSON.parse(await booking()).paidEmail === EMAIL));

await c.navigate(confirmationUrl);
