    window.__posts.push(request ? await request.clone().text() : init?.body);
    if (window.__delay) await new Promise((r) => setTimeout(r, window.__delay));
    if (window.__fail) throw new TypeError('Failed to fetch');
    return origFetch(input, init);
  };
})()`;

  return inject(Router).createUrlTree(['/']);
};

export const bookingPaid: CanActivateFn = () =>
  inject(BookingService).current()?.paidEmail ? true : inject(Router).createUrlTree(['/']);

