results.push(check('confirm clears when email matches again', (await errorOf('confirm-email-error')) === null));

for (const bad of ['12345678', '12345678a', '1234567890']) {
  await setInput('phone-input', bad);
  await blur('phone-input');
  results.push(check(`AC-44 invalid phone "${bad}"`, (await errorOf('phone-error')) === 'Phone number must be exactly 9 digits'));
}
